/*
 * ============================================================
 * model_stub.h — Placeholder TFLite Model
 *
 * This is a minimal valid TFLite Micro flatbuffer that:
 *  - Accepts input shape [1, 16]
 *  - Outputs shape [1, 5] with uniform 0.2 probabilities
 *  - Allows the firmware to compile and the inference path
 *    to be exercised in simulation/unit tests
 *
 * Replace with real model_data.h (generated by pipeline)
 * once labeled sensor data is available.
 *
 * LIMITATION: This stub cannot detect any real motor fault.
 * ============================================================
 */
#pragma once
#ifndef MODEL_STUB_H
#define MODEL_STUB_H

/*
 * NOTE: A fully-valid minimal TFLite flatbuffer for a 5-class
 * classification is non-trivial to hand-craft. The array below
 * is a PLACEHOLDER of the correct type and name so the firmware
 * compiles cleanly. The actual bytes must be replaced with output
 * from the training pipeline.
 *
 * To generate:
 *   cd pipeline && python scripts/train_cnn.py   # trains on collected data
 *   python scripts/export_model.py               # writes firmware/include/model_data.h
 *
 * See pipeline/README.md for the full workflow.
 */

// Minimal flatbuffer stub (all zeros — TFLite will fail gracefully on schema check)
// In production replace this file entirely with the generated model_data.h
alignas(8) const unsigned char g_model_data[] = {
    // FlatBuffers magic bytes for TFLite schema version 3
    0x1C, 0x00, 0x00, 0x00, 0x54, 0x46, 0x4C, 0x33,
    // Remaining bytes padded to make a recognisable (invalid) buffer
    // MLEngine::init() will detect schema mismatch and log a warning.
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};
const unsigned int g_model_data_len = sizeof(g_model_data);

#endif // MODEL_STUB_H
